operation.add:
if ($this->config->get('module_price_match_status')) {
    $this->load->language('extension/module/price_match');
    $allowed_triggers = array('button', 'always', 'delay', 'exit', 'scroll');
    $price_match_trigger = (string)$this->config->get('module_price_match_display_trigger');
    if (!in_array($price_match_trigger, $allowed_triggers)) {
        $price_match_trigger = 'button';
    }

    $price_match_delay_seconds = (int)$this->config->get('module_price_match_display_delay');
    if ($price_match_delay_seconds < 1 || $price_match_delay_seconds > 300) {
        $price_match_delay_seconds = 5;
    }

    $price_match_scroll_pct = (int)$this->config->get('module_price_match_scroll_percent');
    if ($price_match_scroll_pct < 1 || $price_match_scroll_pct > 100) {
        $price_match_scroll_pct = 50;
    }

    $data['price_match_url']          = $this->url->link('extension/module/price_match', 'product_id=' . $product_id, true);
    $data['price_match']              = true;
    $data['text_price_match']         = $this->language->get('button_price_match');
    $data['price_match_trigger']      = $price_match_trigger;
    $data['price_match_delay']        = $price_match_delay_seconds;
    $data['price_match_scroll_pct']   = $price_match_scroll_pct;
} else {
    $data['price_match']              = false;
    $data['price_match_url']          = '';
    $data['text_price_match']         = '';
    $data['price_match_trigger']      = 'button';
    $data['price_match_delay']        = 5;
    $data['price_match_scroll_pct']   = 50;
}

{% if price_match %}
<div class="price-match-wrapper" style="margin-top:10px;">

  {# Show the button for button-click and auto-trigger modes (hidden for 'always') #}
  {% if price_match_trigger != 'always' %}
  <a href="javascript:void(0);"
     class="btn btn-default btn-sm"
     id="button-price-match"
     data-url="{{ price_match_url|e('html_attr') }}">
    <i class="fa fa-tags"></i> {{ text_price_match }}
  </a>
  {% endif %}

  {# Inline container — visible only for 'always' trigger #}
  {% if price_match_trigger == 'always' %}
  <div id="price-match-inline">
    <div class="text-center"><i class="fa fa-spinner fa-spin fa-2x"></i></div>
  </div>
  {% endif %}

</div>

<!-- Price Match Modal (used by button / delay / exit / scroll triggers) -->
{% if price_match_trigger != 'always' %}
<div id="modal-price-match" class="modal fade" tabindex="-1" role="dialog" aria-labelledby="modal-price-match-label">
  <div class="modal-dialog" role="document">
    <div class="modal-content">
      <div class="modal-header">
        <button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button>
        <h4 class="modal-title" id="modal-price-match-label">{{ text_price_match }}</h4>
      </div>
      <div class="modal-body" id="modal-price-match-body">
        <div class="text-center"><i class="fa fa-spinner fa-spin fa-2x"></i></div>
      </div>
    </div>
  </div>
</div>
{% endif %}

<script type="text/javascript">
(function () {
    var pmUrl      = '{{ price_match_url|e('js') }}';
    var pmTrigger  = '{{ price_match_trigger|e('js') }}';
    var pmDelay    = {{ price_match_delay }};
    var pmScroll   = {{ price_match_scroll_pct }};
    var pmFired    = false;
    var pmLoaded   = false;
    var pmSessionKey      = 'price_match_shown_{{ product_id|e('js') }}_' + pmTrigger;
    var pmExitThreshold   = 10;   // px from top of viewport for exit-intent detection
    var pmScrollThrottleMs = 150; // ms between scroll-depth checks

    /* ---------- helpers ---------- */
    function pmSessionFired() {
        try { return sessionStorage.getItem(pmSessionKey) === '1'; } catch(e) { return false; }
    }
    function pmMarkFired() {
        try { sessionStorage.setItem(pmSessionKey, '1'); } catch(e) {}
        pmFired = true;
    }

    function loadPriceMatchForm(callback) {
        if (pmLoaded) { if (callback) callback(); return; }
        $.ajax({
            url: pmUrl, type: 'GET', dataType: 'json',
            success: function (json) {
                if (json['html']) {
                    pmLoaded = true;
                    if (pmTrigger === 'always') {
                        $('#price-match-inline').html(json['html']);
                    } else {
                        $('#modal-price-match-body').html(json['html']);
                    }
                    if (callback) callback();
                }
            }
        });
    }

    function openPriceMatchModal() {
        if (pmFired || pmSessionFired()) return;
        pmMarkFired();
        loadPriceMatchForm(function () {
            $('#modal-price-match').modal('show');
        });
    }

    /* ---------- button click ---------- */
    if (pmTrigger === 'button') {
        $('#button-price-match').on('click', function () {
            loadPriceMatchForm(function () {
                $('#modal-price-match').modal('show');
            });
        });
    }

    /* ---------- always visible ---------- */
    if (pmTrigger === 'always') {
        $(document).ready(function () {
            loadPriceMatchForm();
        });
    }

    /* ---------- time delay ---------- */
    if (pmTrigger === 'delay') {
        $(document).ready(function () {
            setTimeout(openPriceMatchModal, pmDelay * 1000);
        });
    }

    /* ---------- exit intent ---------- */
    if (pmTrigger === 'exit') {
        $(document).on('mouseleave', function (e) {
            if (e.clientY < pmExitThreshold) {
                openPriceMatchModal();
            }
        });
    }

    /* ---------- scroll depth ---------- */
    if (pmTrigger === 'scroll') {
        var pmScrollThrottle = false;
        $(window).on('scroll', function () {
            if (pmScrollThrottle || pmFired || pmSessionFired()) return;
            pmScrollThrottle = true;
            setTimeout(function () {
                pmScrollThrottle = false;
                var scrolled = $(window).scrollTop();
                var docHeight = $(document).height() - $(window).height();
                if (docHeight > 0 && (scrolled / docHeight) >= (pmScroll / 100)) {
                    openPriceMatchModal();
                }
            }, pmScrollThrottleMs);
        });
    }
})();
</script>
{% endif %}
